'use client';

import React, { useEffect, useRef, useState } from 'react';
import { FRONT_WIDTH, FRONT_HEIGHT, type FrontFit } from '@/lib/paperback-cover';
import type { PreparedFrontImage } from '@/lib/paperback-cover-browser';

interface Props {
  loadEpubCover: () => Promise<Blob>;
  onChange: (front: PreparedFrontImage | null) => void;
  file: File | null;
  fit: FrontFit;
  backgroundColor: string;
  saved?: boolean;
  onFileChange: (file: File | null) => void;
  onFitChange: (fit: FrontFit) => void;
}

export default function PaperbackFrontImage({ loadEpubCover, onChange, file, fit, backgroundColor, saved = false, onFileChange, onFitChange }: Props) {
  const [front, setFront] = useState<PreparedFrontImage | null>(null);
  const [error, setError] = useState('');
  const input = useRef<HTMLInputElement>(null);
  const epubCover = useRef<Promise<Blob> | null>(null);

  useEffect(() => { epubCover.current = null; }, [loadEpubCover]);
  useEffect(() => {
    let active = true;
    setFront(null); onChange(null); setError('');
    const prepare = async () => {
      if (file && !(['image/jpeg', 'image/png'].includes(file.type) || (!file.type && /\.(jpe?g|png)$/i.test(file.name)))) {
        throw new Error('Choose a JPG or PNG image for the front cover.');
      }
      if (!file && !epubCover.current) {
        epubCover.current = loadEpubCover().catch(failure => { epubCover.current = null; throw failure; });
      }
      const blob = file ?? await epubCover.current!;
      if (!active) return;
      const { prepareFrontImage } = await import('@/lib/paperback-cover-browser');
      if (!active) return;
      const prepared = await prepareFrontImage(blob, fit, backgroundColor);
      if (active) { setFront(prepared); onChange(prepared); }
    };
    void prepare().catch(failure => {
      if (active) setError(failure instanceof Error ? failure.message : 'This image could not be opened. Choose another JPG or PNG.');
    });
    return () => { active = false; onChange(null); };
  }, [file, fit, backgroundColor, loadEpubCover, onChange]);

  return (
    <div className='space-y-2'>
      <h4 className='font-semibold'>Front-cover image</h4>
      <p className='text-xs text-base-content/70'>Choose finished artwork with its title and author. Click Save to keep it with this ebook, replacing any previously saved paperback image.</p>
      <div>
        <button type='button' className='btn btn-outline btn-sm' onClick={() => input.current?.click()}>Choose image</button>
        <input ref={input} type='file' hidden aria-label='Choose front-cover image' accept='.jpg,.jpeg,.png,image/jpeg,image/png'
          onChange={event => { const selected = event.target.files?.[0]; event.target.value = ''; if (selected) { onChange(null); setFront(null); onFileChange(selected); } }} />
      </div>
      <div className='flex flex-wrap items-center gap-3 text-sm'>
        <span className='break-all'>{file ? `${file.name} · ${saved ? 'Saved with this ebook' : 'Not saved yet'}` : 'Using the EPUB cover'}</span>
        {file && <button type='button' className='link' onClick={() => { onChange(null); setFront(null); onFileChange(null); if (input.current) input.current.value = ''; }}>Use EPUB cover</button>}
      </div>
      <label className='block text-sm'>Image placement
        <select className='select select-bordered select-sm mt-1 w-full' value={fit}
          onChange={event => { onChange(null); setFront(null); onFitChange(event.target.value as FrontFit); }}>
          <option value='fill'>Fill front cover — no added border</option>
          <option value='border'>Keep whole image — add a border</option>
        </select>
      </label>
      <p className='text-xs text-base-content/70'>Front artwork including bleed: 6.125 × 9.25 inches.</p>
      {error ? <p role='alert' className='text-sm text-error'>{error}</p> : !front ? <p role='status' className='text-sm'>Preparing the front-cover preview…</p> : (
        <>
          <div className='relative mx-auto w-44 max-w-full overflow-hidden' style={{ aspectRatio: `${FRONT_WIDTH} / ${FRONT_HEIGHT}` }}>
            {/* The preview uses the exact panel that will be placed in the PDF. */}
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={front.dataUrl} alt='Front-cover preview including bleed' className='block h-full w-full' />
            <div aria-hidden='true' className='pointer-events-none absolute border border-dashed border-white'
              style={{ left: `${0.125 / FRONT_WIDTH * 100}%`, right: `${0.25 / FRONT_WIDTH * 100}%`, top: `${0.25 / FRONT_HEIGHT * 100}%`, bottom: `${0.25 / FRONT_HEIGHT * 100}%`, boxShadow: '0 0 0 1px #333' }} />
          </div>
          <p className='text-xs text-base-content/70'>Dashed guide: keep the title, author name and important details inside. The guide is not printed. PNG transparency is flattened to the chosen background color when you select the image. To change that color inside an uploaded PNG, select the PNG again.</p>
          <p className='text-xs text-base-content/70'>{front.sourceWidth} × {front.sourceHeight} pixels · approximately {Math.round(front.dpi)} DPI at the chosen print size</p>
          {front.warnings.length > 0 && <ul className='list-disc space-y-2 pl-5 text-sm'>{front.warnings.map(message => <li key={message}>{message}</li>)}</ul>}
        </>
      )}
    </div>
  );
}

import type JSZip from 'jszip';
import { createPaperbackCover } from 'book-pdf/cover';
import { extractEpubCover } from './epub-cover';
import { COVER_BACKGROUND, coverBackground, coverTextColor, FRONT_WIDTH, FRONT_HEIGHT, coverDimensions, frontPlacement, frontImageWarnings, paperbackPublishingNote, type FrontFit, type PaperbackCoverOptions } from './paperback-cover';

export interface PreparedFrontImage {
  dataUrl: string;
  sourceWidth: number;
  sourceHeight: number;
  dpi: number;
  fit: FrontFit;
  warnings: string[];
}

// Keep the whole uploaded artwork in the one saved JPEG, so placement can change.
export async function normalizeFrontUpload(file: File, backgroundColor: string = COVER_BACKGROUND): Promise<{ name: string; jpeg: string }> {
  if (!(['image/jpeg', 'image/png'].includes(file.type) || (!file.type && /\.(jpe?g|png)$/i.test(file.name)))) {
    throw new Error('Choose a JPG or PNG image for the front cover.');
  }
  const url = URL.createObjectURL(file);
  const canvas = document.createElement('canvas');
  try {
    const image = new Image(); image.src = url; await image.decode();
    const placement = frontPlacement(image.naturalWidth, image.naturalHeight, 'fill');
    const scale = Math.min(1, 300 / placement.dpi);
    canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Your browser could not prepare the cover image.');
    context.fillStyle = coverBackground(backgroundColor); context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const jpeg = canvas.toDataURL('image/jpeg', 0.95);
    if (!jpeg.startsWith('data:image/jpeg;base64,')) throw new Error('This image is too large for your browser. Choose a smaller JPG or PNG.');
    return { name: file.name.replace(/\.[^.]*$/, '') + '.jpg', jpeg };
  } finally { canvas.width = canvas.height = 1; URL.revokeObjectURL(url); }
}

export async function prepareFrontImage(blob: Blob, fit: FrontFit = 'fill', backgroundColor: string = COVER_BACKGROUND): Promise<PreparedFrontImage> {
  const url = URL.createObjectURL(blob);
  try {
    const image = new Image();
    image.src = url;
    await image.decode();
    const placement = frontPlacement(image.naturalWidth, image.naturalHeight, fit);
    // Prepare only the front panel. Cap at 300 DPI; do not upscale small images.
    const dpi = Math.min(300, placement.dpi);
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(FRONT_WIDTH * dpi));
    canvas.height = Math.max(1, Math.round(FRONT_HEIGHT * dpi));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Your browser could not prepare the cover image.');
    context.fillStyle = coverBackground(backgroundColor);
    context.fillRect(0, 0, canvas.width, canvas.height);
    // Separate scales account for whole-pixel canvas rounding at its outer edges.
    const sx = canvas.width / FRONT_WIDTH, sy = canvas.height / FRONT_HEIGHT;
    context.drawImage(image, placement.x * sx, placement.y * sy, placement.width * sx, placement.height * sy);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
    // Free the pixel buffer promptly when creating large illustrated books.
    canvas.width = canvas.height = 1;
    if (!dataUrl.startsWith('data:image/jpeg;base64,')) throw new Error('Your browser could not prepare this image. Choose another JPG or PNG.');
    return { dataUrl, sourceWidth: image.naturalWidth, sourceHeight: image.naturalHeight,
      dpi: placement.dpi, fit, warnings: frontImageWarnings(image.naturalWidth, image.naturalHeight, fit) };
  } finally { URL.revokeObjectURL(url); }
}

export interface PaperbackCoverResult {
  blob: Blob;
  warnings: string[];
  dimensions: ReturnType<typeof coverDimensions>;
}

export async function generatePaperbackCover(
  zip: JSZip, pageCount: number, options: PaperbackCoverOptions,
  title: string, author: string, cancelled: () => boolean = () => false,
  selectedFront?: PreparedFrontImage,
): Promise<PaperbackCoverResult> {
  const check = () => { if (cancelled()) throw new DOMException('Cancelled', 'AbortError'); };
  check();
  const dimensions = coverDimensions(pageCount, options.paper);
  const backgroundColor = coverBackground(options.backgroundColor);
  const front = selectedFront ?? await prepareFrontImage(await extractEpubCover(zip), 'fill', backgroundColor);
  check();
  const result = await createPaperbackCover({
    backgroundColor, textColor: coverTextColor(backgroundColor),
    title, author, backText: options.backText, printPages: dimensions.printPages,
    spine: dimensions.spine, frontImage: front.dataUrl, frontWidth: FRONT_WIDTH, frontHeight: FRONT_HEIGHT, frontFullBleed: true,
  });
  check();
  const warnings = [...front.warnings, ...result.warnings];
  const publishingNote = paperbackPublishingNote(pageCount, options.paper);
  if (publishingNote) warnings.push(publishingNote);
  if (dimensions.pdfPages !== dimensions.printPages) warnings.push(
    `The PDF has ${dimensions.pdfPages} pages. The cover allows for ${dimensions.printPages}, because KDP rounds up to an even page count.`,
  );
  return { blob: result.blob, dimensions, warnings };
}
